package receipt

import (
	"crypto/ed25519"
	"crypto/rand"
	"strings"
	"testing"
)

// Sixty-four random bytes are the right length for an Ed25519 private key
// and are not one. They are also what `openssl rand -base64 64` produces,
// which is the obvious command to reach for when a deployment's signing
// key has to be generated by hand.
//
// Accepted, such a key signs with its seed and publishes the unrelated
// half, so the deployment looks healthy and every receipt it issues is
// unverifiable by the person it was issued for. There is no later check
// that catches this: the signature is well-formed, the key file is served,
// and nothing in the service ever verifies its own output.
func TestAPrivateKeyWhoseHalvesDisagreeIsRefused(t *testing.T) {
	raw := make([]byte, ed25519.PrivateKeySize)
	if _, err := rand.Read(raw); err != nil {
		t.Fatal(err)
	}

	_, err := NewEd25519Signer("drill-1", ed25519.PrivateKey(raw))
	if err == nil {
		t.Fatal("a private key whose public half does not match its seed was accepted; " +
			"every receipt signed with it would fail verification")
	}
	// The operator has to be told what to do, not only that something is
	// wrong: the remedy is passing the 32-byte seed.
	if !strings.Contains(err.Error(), "seed") {
		t.Errorf("the refusal does not tell the operator to use the seed: %v", err)
	}
}

// The real thing still works, in both the forms the server accepts.
func TestAWellFormedKeyPairIsAccepted(t *testing.T) {
	_, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := NewEd25519Signer("drill-1", priv); err != nil {
		t.Fatalf("a generated key pair was refused: %v", err)
	}
	if _, err := NewEd25519Signer("drill-1", ed25519.NewKeyFromSeed(priv.Seed())); err != nil {
		t.Fatalf("a key rebuilt from its own seed was refused: %v", err)
	}
}

// The property the check exists to protect, stated as the thing a verifier
// does: what the deployment publishes must verify what the deployment
// signs. A length check cannot see this and never could.
func TestWhatIsSignedVerifiesUnderWhatIsPublished(t *testing.T) {
	s, err := GenerateEd25519Signer("drill-1")
	if err != nil {
		t.Fatal(err)
	}
	sig, err := s.Sign([]byte("a receipt's signing input"))
	if err != nil {
		t.Fatal(err)
	}
	pub, ok := s.Public().(ed25519.PublicKey)
	if !ok {
		t.Fatalf("Public() returned %T", s.Public())
	}
	if !ed25519.Verify(pub, []byte("a receipt's signing input"), sig) {
		t.Error("a signature did not verify under the key this signer publishes")
	}
}
